'use client';
import React from 'react';
import Link from 'next/link';
import { motion } from 'framer-motion';
import { ArrowRight, Rocket } from 'lucide-react';

export default function HomePage() {
  return (
    <div className="relative min-h-screen bg-[#FDFEFE] text-slate-800 flex flex-col justify-between overflow-hidden font-sans p-6">
      
      {/* DECORACIÓN DE FONDO */}
      <div className="absolute top-0 right-0 w-[42vw] h-[45vh] bg-gradient-to-bl from-sky-400/20 via-blue-500/10 to-indigo-600/5 rounded-bl-[140px] -z-0 pointer-events-none" />
      
      <header className="relative z-10 max-w-4xl w-full mx-auto py-12 text-center">
        <motion.h1 
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            className="text-5xl font-black text-slate-900 tracking-tight"
        >
          WISDOM <span className="text-sky-600">SCHOOL</span>
        </motion.h1>
        <p className="mt-4 text-slate-500 font-medium tracking-wide uppercase text-xs">Homeschool Academy</p>
      </header>

      <main className="relative z-10 max-w-2xl w-full mx-auto space-y-8 my-auto">
        
        {/* TARJETA AVRIL */}
        <motion.div whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }}>
          <Link href="/aula/avril" className="group block bg-white p-8 rounded-3xl border border-indigo-100 shadow-xl hover:shadow-2xl transition-all">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className="w-16 h-16 rounded-2xl bg-indigo-600 text-white flex items-center justify-center text-2xl font-black">A</div>
                <div>
                  <h2 className="text-2xl font-black text-slate-900">Avril</h2>
                  <span className="text-xs font-bold text-indigo-600 uppercase">12 Años • 8vo de Básica</span>
                </div>
              </div>
              <ArrowRight className="text-slate-300 group-hover:text-indigo-600 transition-colors" />
            </div>
          </Link>
        </motion.div>

        {/* TARJETA GAEL */}
        <motion.div whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }}>
          <Link href="/aula/gael" className="group block bg-white p-8 rounded-3xl border border-amber-100 shadow-xl hover:shadow-2xl transition-all">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className="w-16 h-16 rounded-2xl bg-amber-500 text-white flex items-center justify-center text-2xl font-black">G</div>
                <div>
                  <h2 className="text-2xl font-black text-slate-900">Gael</h2>
                  <span className="text-xs font-bold text-amber-600 uppercase">8 Años • 4to de Básica</span>
                </div>
              </div>
              <Rocket className="text-slate-300 group-hover:text-amber-500 transition-colors" />
            </div>
          </Link>
        </motion.div>

      </main>

      <footer className="relative z-10 text-center py-8 text-xs text-slate-400 font-medium">
        © Wisdom School • Ecosistema Educativo Personalizado
      </footer>
    </div>
  );
}
